query RetrieveBooking($bookingRef: String!, $firstName: String!, $lastName: String!) {
  retrieveBooking(bookingRef: $bookingRef, firstName: $firstName, lastName: $lastName) {
    recordLocator
    bookingDate
    segments {
      cabin
      departure
      destination
      eligibility
      marketingFlight {
        airlineCode
        number
      }
      operatingFlight {
        airlineCode
        number
      }
      origin
      segmentID
    }
    passengers {
      firstName
      frequentFlyerNumber
      lastName
      passengerId
      selectedMeal
    }
  }
}
